<script setup lang="ts">
import type { ApiSuccess } from '~/types/api'
definePageMeta({layout:'dashboard',middleware:'auth'});useHead({title:'Support'})
type Ticket={id:string;number:string;category:string;priority:string;status:string;subject:string;createdAt:string;updatedAt:string;_count:{comments:number}}
const {data,error,refresh}=await useFetch<ApiSuccess<Ticket[]>>('/api/tickets');const tickets=computed(()=>data.value?.data??[]);const date=(v:string)=>new Date(v).toLocaleString('fr-FR')
</script>
<template><div><div class="page-head"><div><h1>Support & tickets</h1><p>Incidents et demandes adressés aux équipes IFICS.</p></div><button class="btn btn-secondary" type="button" @click="refresh()">Actualiser</button></div><div v-if="error" class="alert alert-error">Impossible de charger les tickets.</div><div v-else-if="!tickets.length" class="empty-state">Aucun ticket ouvert ou historique accessible.</div><div v-else class="table-wrap"><table><thead><tr><th>Ticket</th><th>Objet</th><th>Catégorie</th><th>Priorité</th><th>Commentaires</th><th>Statut</th><th>Mis à jour</th></tr></thead><tbody><tr v-for="ticket in tickets" :key="ticket.id"><td><strong>{{ ticket.number }}</strong></td><td>{{ ticket.subject }}</td><td>{{ ticket.category }}</td><td><span class="badge" :class="ticket.priority==='URGENT'?'badge-danger':ticket.priority==='HIGH'?'badge-warning':''">{{ ticket.priority }}</span></td><td>{{ ticket._count.comments }}</td><td>{{ ticket.status }}</td><td>{{ date(ticket.updatedAt) }}</td></tr></tbody></table></div></div></template>
